        // Team role & form fields (2.16.0)
        'staff.help.step1': 'Em Usuários, crie a conta da pessoa (ou edite a que já tem) com a função «Equipe da conferência». Essa função só a deixa entrar em «Conference» e na sua própria conta, em nenhuma outra página do administrador. (Já tem outra função, por exemplo Editor? Dê a essa função a permissão «conference_manager_access» em Usuários › Funções: mantém as suas páginas e entra também aqui.)',
        'staff.help.step2': 'Aqui, em Membros, adicione-a à equipe e escolha a sua função na equipe: decide que seções vê ou gerencia.',
        'staff.help.step3': 'Ela entra com a sua própria conta em /admin e chega diretamente em «Conference».',
        'staff.help.users.link': 'Abrir Usuários',
        'staff.add.hint.team': 'Procure um usuário do WordJS pelo nome, e-mail ou usuário e escolha a sua função na equipe. Só é possível adicionar contas cuja função do WordJS dá acesso a «Conference»: a função «Equipe da conferência», ou outra função com a permissão «conference_manager_access». Se ainda não tiver conta, crie-a em Usuários com essa função.',
        'staff.add.not.team.role': 'Não é possível adicionar: a sua função não dá acesso a «Conference». Dê-lhe a função «Equipe da conferência» em Usuários, ou a permissão «conference_manager_access» à sua função em Usuários › Funções.',
        'staff.wprole.label': 'Função no WordJS: {role}',
