        'staff.member.no.role.hint': 'A conta tem a função do WordJS «{role}», que não dá acesso a «Conference». Dê a função «Equipe da conferência» em Usuários, ou a permissão «conference_manager_access» a essa função em Usuários › Funções; ou retire-a da equipe.',
